INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1167, 'repo-health-code-pilot', 'id(web): blockquote starting with code/table/rule gains two stray blank lines on save — triage', '{"kind":"triage","repo":"developing-today/code","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/code/issues/1002","title":"id(web): saving a blockquote that starts with a code block, table or rule inserts two stray blank lines at the top of the quote","number":1002,"state_checked_at":"2026-10-26T19:18:00Z"},"scope":{"exclude":["#954 no-info code blocks rewritten as indented blocks","comrak upstream changes"],"include":["pkgs/id/src/web/markdown.rs save direction (prosemirror_to_markdown / json_to_ast blockquote handling) and codec tests"]},"tests":["cargo test --features web --lib web::markdown (targeted)"],"dedupe":{"basis":"gh issue search (all states) for ''blockquote blank'' and ''stray blank lines quote'' returned no matching issue; #954 is a distinct mechanism (indented rewrite of no-info blocks).","checked_at":"2026-10-26T19:18:00Z"},"schema":"repo-task/v1","problem":"First save of a file whose blockquote starts with a code block, table or rule pollutes the quote with two stray blank lines; renders with a gap and creates diff noise, though the PM document is correct and the result is a stable fixpoint.","evidence":["markdown.rs:868-874 prosemirror_to_markdown -> format_commonmark on hand-built AST","Probe main 3b9d1592 (hidden_files/probe-2026-10-26-1415/out3.log): quote-fence-lang, quote-table-first, quote-hr-first all gain two leading ''> '' lines; paragraph/heading/list-first controls and paragraph-then-fence control are clean","Direct comrak parse->format_commonmark control reproduces the same two lines, isolating the renderer behaviour the save direction inherits"],"acceptance":["Round-trip byte-identical for blockquote starting with fenced code block (with info string), table, and thematic break + text","Controls unchanged: quote starting with paragraph/heading/list, and paragraph-then-fence inside a quote keeps exactly one separator blank line","Existing web::markdown tests pass \u2014 or unfixable-without-fork rationale recorded and issue closed"],"context_refs":["https://github.com/developing-today/code/issues/1002","pkgs/id/src/web/markdown.rs:868"],"max_attempts":3,"priority_reason":"Cosmetic file pollution on save, no data loss and a stable fixpoint, so low priority.","timebox_minutes":20}', 'queued', 70, 'repo-health:v1:triage:developing-today/code:issue:1002', '2026-10-26 19:18:35.314815+00', '2026-10-27 04:56:20.500413+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1168, 'repo-health-code-pilot', 'id(web): multi-paragraph table cell fuses words on save — triage', '{"kind":"triage","repo":"developing-today/code","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/code/issues/1003","title":"id(web): a table cell with two paragraphs is fused into one word on save \u2014 paragraphs concatenated with no separator","number":1003,"state_checked_at":"2026-10-26T19:20:00Z"},"scope":{"exclude":["GFM table parsing (parse direction never yields multi-paragraph cells)","editor schema changes"],"include":["pkgs/id/src/web/markdown.rs json_to_ast table_header/table_cell unwrap branch and codec tests"]},"tests":["cargo test --features web --lib web::markdown (targeted)"],"dedupe":{"basis":"gh issue search (all states) for ''table cell two paragraphs'' and ''cell paragraphs concatenated'' returned no issues.","checked_at":"2026-10-26T19:20:00Z"},"schema":"repo-task/v1","problem":"Editor/collab-originated table cells with more than one paragraph lose the paragraph boundary on save, fusing words (''first''+''second'' -> ''firstsecond''); unrecoverable after one save.","evidence":["markdown.rs ~:1080-1098 cell unwrap loop appends inline children paragraph after paragraph with no separator node","Probe main 3b9d1592 (hidden_files/probe-2026-10-26-1415/out4.log, case cell-two-paras): PM cell [para ''first'', para ''second''] -> ''| firstsecond |'', reparse single text ''firstsecond'', SAMEPM false"],"acceptance":["Cell with two paragraphs saves with a separator, no word fusion; reparse keeps both words separate","Single-paragraph cells and all parse-direction tables save byte-identically to today","Three-paragraph cell and two-paragraph header cell behave the same","Existing web::markdown table tests pass"],"context_refs":["https://github.com/developing-today/code/issues/1003","pkgs/id/src/web/markdown.rs:1080"],"max_attempts":3,"priority_reason":"Silent content corruption (word fusion) on save for editor-authored multi-paragraph cells; parse-direction documents unaffected, so normal priority.","timebox_minutes":20}', 'queued', 50, 'repo-health:v1:triage:developing-today/code:issue:1003', '2026-10-26 19:20:33.000813+00', '2026-10-27 04:56:20.500413+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1169, 'repo-health-code-pilot', 'id(web): unused link reference definitions deleted on save — triage design', '{"kind":"triage","repo":"developing-today/code","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/code/issues/1004","title":"id(web): unused link reference definitions are silently deleted on save \u2014 a definitions-only document saves as an empty file","number":1004,"state_checked_at":"2026-10-26T19:21:00Z"},"scope":{"exclude":["footnote definitions (#945, separate mechanism)","editor UI for managing references"],"include":["pkgs/id/src/web/markdown.rs codec + module documentation; editor schema only if triage chooses the PM-node design"]},"tests":["cargo test --features web --lib web::markdown (targeted)"],"dedupe":{"basis":"gh issue search (all states) for ''reference definition'' and ''unused reference'' returned no codec issue (#945 is footnotes, a distinct syntax/mechanism).","checked_at":"2026-10-26T19:21:00Z"},"schema":"repo-task/v1","problem":"Opening a markdown file in the id web editor and saving deletes every link reference definition that no current link uses; a definitions-only file becomes empty. No warning, no representation in the editor.","evidence":["Probe main 3b9d1592 (hidden_files/probe-2026-10-26-1415/out4.log): ''body text + [unused]: https://example.com'' -> PM single paragraph, save ''body text''; definitions-only doc -> empty PM placeholder, save ''''","Controls in same log: shortcut-ref, collapsed-ref, multi-ref-same all round-trip as inlined links \u2014 loss is specific to unused definitions","markdown.rs module doc / PM schema (top of file) defines no node type that could carry a reference definition"],"acceptance":["Unused reference definitions no longer lost silently: they survive a load/save round trip, or the limitation is documented in the markdown.rs module docs and the issue closed citing it","Used references (full/collapsed/shortcut/shared) round-trip exactly as today","Definitions-only document does not save as an empty file under the chosen fix (or is covered by the documented limitation)","Existing web::markdown tests pass"],"context_refs":["https://github.com/developing-today/code/issues/1004","pkgs/id/src/web/markdown.rs:1"],"max_attempts":3,"priority_reason":"Silent deletion of authored content lines on save; used references are unaffected, so normal priority, with a design decision required.","timebox_minutes":25}', 'queued', 50, 'repo-health:v1:triage:developing-today/code:issue:1004', '2026-10-26 19:21:32.494524+00', '2026-10-27 04:56:20.500413+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1170, 'repo-health-openchamber-pilot', 'fix(quota): VS Code Cursor enterprise windowSeconds = cycle duration or null (#506)', '{"prs":[],"set":null,"kind":"small_fix","repo":"developing-today/openchamber","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/openchamber/issues/506","title":"fix(quota): VS Code Cursor enterprise windows report time-until-reset as windowSeconds, not the window duration","number":506,"state_checked_at":"2026-10-26T19:52:00Z"},"scope":{"exclude":["packages/web/server/lib/quota/providers/cursor.js (that is #495, a separate fix in a different file/test suite)","Any change to resetAt/resetAfterSeconds derivation","Other providers in quotaProviders.ts"],"include":["packages/vscode/src/quotaProviders.ts cursorEnterpriseWindows windowSeconds derivation","packages/vscode/src/quotaProviders.test.ts Cursor block enterprise windowSeconds test"]},"tests":["Targeted quotaProviders.test.ts Cursor block passes incl. new windowSeconds assertions","Existing enterprise assertions (usedPercent 59, valueLabel ''590 / 1000'', on_demand ''$6.72 / $250.00'') unchanged"],"dedupe":{"basis":"gh issue list --state all searches ''vscode cursor windowSeconds'' and ''cursorEnterpriseWindows'' returned no tracking issue; #495 is web-provider-only scope","checked_at":"2026-10-26T19:52:00Z"},"schema":"repo-task/v1","problem":"The VS Code port''s Cursor enterprise builder reports time-until-reset as windowSeconds instead of the billing-cycle duration (or null when unknown).","evidence":["Verified 2026-10-26 on main a181e1299: quotaProviders.ts:2491 const windowSeconds = resetAt ? Math.max(0, Math.floor((resetAt - Date.now()) / 1000)) : null; passed to billing_cycle (:2496) and on_demand (:2501)","Port''s own plan path quotaProviders.ts:2538 passes windowSeconds: null for its billing_cycle window","grep ''resetAt - Date.now'' packages/vscode/src: all other sites feed resetAfterSeconds fields; only :2491 assigns to windowSeconds","quotaProviders.test.ts enterprise block (:1861-1975) asserts usedPercent/valueLabel but never windowSeconds; fixtures (:1883) carry billingCycleStart and billingCycleEnd"],"acceptance":["Cursor enterprise windows no longer report time-until-reset as windowSeconds","With billingCycleStart and billingCycleEnd both known from the same payload, windowSeconds equals the cycle duration in seconds; otherwise null","resetAt / resetAfterSeconds behaviour unchanged; existing Cursor quota tests pass","New test in quotaProviders.test.ts pins enterprise windowSeconds (duration case and null case)"],"context_refs":["https://github.com/developing-today/openchamber/issues/506","https://github.com/developing-today/openchamber/issues/495"],"max_attempts":2,"priority_reason":"Wrong duration semantics corrupt the UI headline-window choice for Cursor enterprise users (an ever-shortening window outranks genuine short windows near cycle end); silent data bug, normal priority.","timebox_minutes":45}', 'done', 30, 'repo-health:v1:fix:developing-today/openchamber:issue:506', '2026-10-26 19:48:17.839727+00', '2026-10-27 09:53:27.637235+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1171, 'repo-health-nix-pilot', 'fix(opencode-db-prune): dry-run suggested --apply command must echo --db/--backup/--no-backup/--batch (prune + restore footers) (#900)', '{"prs":[],"set":null,"kind":"small_fix","repo":"dezren39/nix","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/900","title":"opencode-db-prune: dry-run suggested --apply command drops --db (and --no-backup/--backup) \u2014 pasting it prunes the default live DB, not the measured one","number":900,"state_checked_at":"2026-10-26T20:12:56Z"},"scope":{"exclude":["Changing any prune/restore behaviour beyond the printed suggested commands","opencode-db-vacuum.sh (it prints no suggested command)"],"include":["opencode-db-prune.sh dry-run footer (SUGGEST_FLAGS + Finally line) and restore-mode footer"]},"tests":["Scratch-DB dry run with --db/--no-backup: suggested command contains --db and --no-backup and no stale rm line","Scratch-DB restore dry run with --db: suggested command contains --db","bash -n opencode-db-prune.sh clean"],"dedupe":{"basis":"gh issue list --state all on dezren39/nix filtered to prune titles returned #891/#890/#867/#828/#467/#465 (all closed, different defects) and open #659 (unrelated tmp growth); no issue tracks the suggested-command flag echo","checked_at":"2026-10-26T20:12:56Z"},"schema":"repo-task/v1","problem":"The dry-run -> paste-the-suggested-command flow is the script''s primary safety story for a destructive delete, but the suggested command silently retargets the default live database and a different backup profile than the run that was measured and approved.","evidence":["opencode-db-prune.sh:851-853 SUGGEST_FLAGS carries only --protect-days/--protect-roots/--archive; comment at 849-850 states the opposite intent","opencode-db-prune.sh:488 restore-mode footer prints --restore-session/--from/--apply with no --db","Reproduced 2026-10-26 on main 53bde50 with a scratch DB: --db /tmp/pruneprobe/scratch.db --protect-days 0 --no-backup dry run suggested ''./opencode-db-prune.sh --protect-days 0 --apply'' and ''rm /tmp/pruneprobe/scratch.db.prune-backup''; restore dry run against the same scratch DB likewise omitted --db"],"acceptance":["Prune dry-run footer echoes --db (when non-default or always), --backup PATH/--no-backup and --batch alongside the existing flags, shell-quoted","The Finally rm line names the backup path the suggested command will actually create and is omitted or adjusted under --no-backup","Restore-mode footer echoes --db","Re-running the issue''s probes: the printed command executed verbatim operates on the scratch DB and matches the dry-run projection"],"context_refs":["https://github.com/dezren39/nix/issues/900"],"max_attempts":2,"priority_reason":"Safety papercut on a destructive script: following the printed instructions literally deletes from a different database than the one rehearsed; narrow scope, normal priority.","timebox_minutes":45}', 'done', 30, 'repo-health:v1:fix:dezren39/nix:issue:900', '2026-10-26 20:13:57.238664+00', '2026-10-26 20:24:58.308441+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1172, 'repo-health-nix-pilot', 'fix(opencode-db-prune): aborting at the --apply confirmation must not strand the full-size backup or block the retry (#901)', '{"prs":[],"set":null,"kind":"small_fix","repo":"dezren39/nix","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/901","title":"opencode-db-prune: aborting at the confirmation prompt (after the backup step) strands the full-size backup and blocks every retry with ''refusing to overwrite''","number":901,"state_checked_at":"2026-10-26T20:16:00Z"},"scope":{"exclude":["The archive step ordering (already after the prompt)","opencode-db-vacuum.sh swap behaviour (tracked by closed #892)"],"include":["opencode-db-prune.sh --apply ordering of prompt vs backup (and abort cleanup/message)"]},"tests":["Scratch DB: echo n | --apply leaves no .prune-backup; echo y retry then proceeds","Scratch DB: --apply -y deletes as before; bash -n opencode-db-prune.sh clean"],"dedupe":{"basis":"gh issue list --state all on dezren39/nix filtered to abort/prompt/overwrite titles returned only #892 (vacuum swap overwrite, closed) and unrelated items; no issue tracks prune''s prompt-after-backup abort","checked_at":"2026-10-26T20:16:00Z"},"schema":"repo-task/v1","problem":"The abort path of a destructive script leaves the largest artifact of the run (a full database copy) behind and blocks the user''s immediate retry with a confusing refusal \u2014 on the real 40 GB database that is a 40 GB orphan, the exact net-loss outcome the script header warns against.","evidence":["opencode-db-prune.sh: backup step ~875-890 precedes the confirmation prompt at 892-899; abort branch prints ''aborted; nothing deleted'' and exits 0 without removing the backup","Reproduced 2026-10-26 on main 53bde50 with a scratch DB: ''echo n | ./opencode-db-prune.sh --db /tmp/pruneprobe/apply.db --protect-days 0 --apply'' left apply.db.prune-backup on disk; immediate ''echo y'' retry died ''refusing to overwrite existing backup at /tmp/pruneprobe/apply.db.prune-backup''"],"acceptance":["Answering no at the confirmation leaves no new files behind (prompt moved before backup, or this run''s backup removed on abort)","An immediate re-run of the same --apply command after an abort proceeds normally","Abort message reflects reality; pre-existing-backup overwrite refusal unchanged","--yes runs and the delete path are behaviour-identical to before"],"context_refs":["https://github.com/dezren39/nix/issues/901"],"max_attempts":2,"priority_reason":"Safety papercut on a destructive script''s abort path; narrow scope, normal priority.","timebox_minutes":45}', 'cancelled', 30, 'repo-health:v1:fix:dezren39/nix:issue:901', '2026-10-26 20:15:23.531562+00', '2026-10-26 21:25:04.376489+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1173, 'repo-health-code-pilot', 'id(web): fix nested-mark emit for outer-ranked inner marks (#968 follow-up)', '{"kind":"small_fix","repo":"developing-today/code","risk":{"flags":[],"level":"medium"},"issue":{"url":"https://github.com/developing-today/code/issues/968","title":"id(web): nested marks corrupt on save \u2014 em/strike/code inside strong/em gain &#32; entities and multiplied delimiters, several non-fixpoint","number":968,"state_checked_at":"2026-10-26T20:16:00Z"},"scope":{"exclude":["block-level conversion","other comrak extensions","the #944/#953/#999 fixes themselves (regression-check only)"],"include":["pkgs/id/src/web/markdown.rs (create_marked_text, build_mark_chain, append_inline_child, inline emit path in json_to_ast)"]},"tests":["cargo test --features web --lib web::markdown (targeted; note sandbox needs web/dist built and full lib-test compile OOM''d on 2026-10-26 \u2014 iterate via standalone codec crate, rely on PR CI)","new nested-mark fixpoint unit tests"],"dedupe":{"basis":"Follow-up to triage task 1116 on the same issue #968; no other open task or PR covers the mark-chain emit fix (gh pr list checked 2026-10-26T20:09Z: no markdown.rs PR open for #968)","checked_at":"2026-10-26T20:16:00Z"},"schema":"repo-task/v1","problem":"prosemirror_to_markdown emit: create_marked_text builds each text node''s mark chain in canonical rank order (link<strong<em<strikethrough<code, outermost first); append_inline_child (#999) merges adjacent siblings only on identical TOP wrapper. A span with {common+extra} marks whose extra mark ranks outer to the common mark (strong in em/strike, link in em/strong, em in strike) gets top=extra while neighbours get top=common, so no merge occurs and comrak renders fragmented sibling wrappers with &#32; boundary entities and multiplied delimiters.","evidence":["Triage task 1116 re-probe on current main (markdown.rs identical to origin/main), standalone verbatim-codec crate, logs goal hidden_files/probe-2026-10-26-1510-t1116/crate/out.log + out2.log; findings comment https://github.com/developing-today/code/issues/968#issuecomment-6426329267","Still corrupt: ''*em **strong** end*'' -> ''*em&#32;****strong****&#32;end*''; ''~~strike **strong** end~~'' -> ''~~strike&#32;~~**~~strong~~**~~&#32;end~~''; ''*em [link](https://e.com) end*'', ''**strong [link](https://e.com) end**'', ''~~strike *em* end~~'' likewise (all fixpoint-stable now, not growing)","Now clean post-#999: ''**bold ~~strike~~ end**'', ''**bold `code` end**'', ''*em `code` end*'', ''[link *em* text](https://e.com)'', ''**a *b `c` d* e**'', ''*em ~~strike~~ end*''; ''**bold _em_ end**'' clean modulo _em_->*em* normalization","Comrak-direct control (parse + format_commonmark, no ProseMirror) round-trips all cases cleanly \u2014 defect is in our emit AST construction, not comrak, not parse side"],"acceptance":["The 5 still-corrupt inputs above round-trip open->save byte-identical (modulo documented codec normalizations) and a second round-trip is a fixpoint; no &#32; entities for ordinary spaces","All post-#999 clean cases and the #944/#953 cases do not regress","New unit tests in pkgs/id/src/web/markdown.rs cover the full matrix including the double round-trip property","Existing codec tests pass (cargo test --features web --lib web::markdown, or PR CI equivalent)"],"context_refs":["https://github.com/developing-today/code/issues/968","https://github.com/developing-today/code/issues/968#issuecomment-6426329267","pkgs/id/src/web/markdown.rs create_marked_text / append_inline_child"],"max_attempts":2,"priority_reason":"Silent first-save corruption of ordinary nested-emphasis/link writing in user documents; scope now narrow and root-caused.","timebox_minutes":45}', 'done', 40, 'repo-health:v1:fix:developing-today/code:issue:968', '2026-10-26 20:16:47.096912+00', '2026-10-27 04:15:33.878811+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1175, 'repo-health-code-pilot', 'id(web): preserve HTML blocks on save via code_block provenance attr (#982)', '{"kind":"small_fix","repo":"developing-today/code","risk":{"flags":[],"level":"medium"},"issue":{"url":"https://github.com/developing-today/code/issues/982","title":"id(web): HTML blocks (comments, <details>, <div>) are rewritten as ```html code blocks on save","number":982,"state_checked_at":"2026-10-26T20:50:00Z"},"scope":{"exclude":["inline HTML handling (#943)","other block types","editor UI rendering of HTML blocks","retro-converting already-saved fenced docs"],"include":["pkgs/id/src/web/markdown.rs (HtmlBlock parse arm, code_block emit arm in json_to_ast, code_block PM attrs)"]},"tests":["cargo test --features web --lib web::markdown (targeted; note sandbox needs web/dist built and full lib-test compile OOM''d on 2026-10-26 \u2014 iterate via standalone codec crate, rely on PR CI)","new HTML-block round-trip unit tests"],"dedupe":{"basis":"Follow-up to triage task 1133 on the same issue #982; the only other HTML codec work is #943 (inline HTML, separate task/PR #1009) \u2014 different scope (inline vs block), verified from issue titles/scopes 2026-10-26","checked_at":"2026-10-26T20:50:00Z"},"schema":"repo-task/v1","problem":"NodeValue::HtmlBlock parse arm converts non-img HTML blocks to code_block{params:html}; json_to_ast''s code_block arm always emits a fenced NodeCodeBlock, and converted blocks are shape-identical in PM to authored ```html fences, so HTML comments become visible code fences and <details> blocks are destroyed on any save.","evidence":["Triage task 1133 re-probe on current main, standalone verbatim-codec crate, logs goal hidden_files/probe-2026-10-26-1510-t1116/crate/out4.log: comment/details/div all rewritten as ```html fences; authored fence round-trips clean","PM shapes for converted HTML block vs authored ```html fence verified shape-identical (both code_block attrs{params:html}) \u2014 provenance must be recorded at parse time","Design recorded on issue #982 in the triage findings comment (task 1133)"],"acceptance":["''<!-- comment -->'', ''<details>...</details>'', and a bare ''<div>'' block round-trip byte-identical; second round-trip is a fixpoint","A user-authored ```html fenced block still round-trips as a fenced code block","Already-converted stored docs (params=html, no provenance attr) still emit as fences (no behavior change for them)","New unit tests in pkgs/id/src/web/markdown.rs cover the matrix including the double round-trip property","Existing codec tests pass; #943/#944/#953/#968/#981 cases do not regress"],"context_refs":["https://github.com/developing-today/code/issues/982","pkgs/id/src/web/markdown.rs HtmlBlock parse arm + code_block emit arm (json_to_ast)"],"max_attempts":2,"priority_reason":"Every save of a document containing an HTML comment or <details>/<div> block permanently destroys that markup; fix is bounded to one codec file with a chosen design.","timebox_minutes":45}', 'done', 40, 'repo-health:v1:fix:developing-today/code:issue:982', '2026-10-26 20:25:49.806508+00', '2026-10-27 03:49:21.801086+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1177, 'repo-health-opencode-pilot', 'fix(core): extend redactBody to common credential formats (#541)', '{"prs":[],"set":null,"kind":"small_fix","repo":"developing-today/opencode","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/opencode/issues/541","title":"fix(core): captured provider error bodies leak common credential shapes \u2014 redactBody only covers Bearer, key-fields and sk/pk/rk keys","number":541,"state_checked_at":"2026-10-26T20:43:41Z"},"scope":{"exclude":["error_body capture opt-in gating","2,000-char cap"],"include":["packages/core/src/model-route-log.ts redactBody","packages/core/test/model-route-log.test.ts"]},"tests":["bun test test/model-route-log.test.ts from packages/core"],"dedupe":{"basis":"gh issue search for redact/redactBody/error body returned no covering issue (open or closed)","checked_at":"2026-10-26T20:43:41Z"},"schema":"repo-task/v1","problem":"redactBody misses common credential formats, so captured provider error bodies can persist live credentials to disk.","evidence":["Probe on main 61c35a0228 (temporary bun script, removed after): failureFields with captureBody:true leaked FULLTOKEN for ghp, github_pat, aws, slack, google, jwt, basic, urlpass cases; bearer and sk cases redacted","model-route-log.ts:221-228 redactBody has only three replace patterns"],"acceptance":["error_body contains none of: ghp_/gho_/ghu_/ghs_/ghr_/github_pat_ tokens, AKIA/ASIA key ids, xox[baprs]- tokens, AIza keys, three-segment JWTs, Basic base64 credentials, URL-userinfo passwords","Ordinary non-secret body text is unchanged (no over-redaction)","bun test test/model-route-log.test.ts from packages/core passes"],"context_refs":["https://github.com/developing-today/opencode/issues/541"],"max_attempts":2,"priority_reason":"Persisted credential leak: captured provider error bodies are written to the route-attem