INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1292, 'repo-health-code-pilot', 'id(web): .txt final-newline/CRLF fidelity — triage', '{"kind":"triage","repo":"developing-today/code","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/code/issues/1307","title":"id(web): every .txt open\u2192save drops the final newline (and rewrites CRLF to LF) \u2014 Plain mode is not byte-faithful unlike Raw","number":1307,"state_checked_at":"2026-10-27T05:34:14Z"},"scope":{"exclude":["changing Markdown or Raw mode conversion","fixing the block-type dropping covered by #1306 (same function, separate issue)"],"include":["pkgs/id/src/web/markdown.rs plain_text_to_prosemirror and/or pkgs/id/src/web/routes.rs extract_plain_text + round-trip tests"]},"tests":["targeted cargo test for the plain load->save round-trip shapes"],"dedupe":{"basis":"gh issue searches this run (txt/plain/trailing newline terms, all states) returned no issue tracking plain-mode newline/CRLF fidelity; sibling #1306 covers block dropping in the same function, a different defect.","checked_at":"2026-10-27T05:34:14Z"},"schema":"repo-task/v1","problem":"Plain mode load->save is not byte-faithful: the final newline is unrecoverable after lines() and CRLF is normalized away silently.","evidence":["Probe on origin/main 90f7ea00 (hidden_files/probe-2026-10-26-2352/out3.log): \"alpha\\nbeta\\n\" -> \"alpha\\nbeta\"; \"alpha\\n\" -> \"alpha\"; \"\\n\" -> \"\"; \"alpha\\r\\nbeta\\r\\n\" -> \"alpha\\nbeta\"; controls \"alpha\\nbeta\" and \"\" round-trip exactly","Raw mode contrast: raw_text_to_prosemirror keeps the whole file in one code_block and extract_raw_text returns it byte-exactly"],"acceptance":["No-edit open->save of a .txt file is byte-stable for trailing-newline present/absent shapes, per the documented policy","CRLF handling is either preserved or an explicitly documented + tested normalization","Regression tests run the real load->save pair on: a\\nb\\n, a\\nb, a\\n, empty, and a CRLF sample","Markdown and Raw behavior unchanged"],"context_refs":["https://github.com/developing-today/code/issues/1307","pkgs/id/src/web/markdown.rs:1825","pkgs/id/src/web/routes.rs:2009"],"max_attempts":3,"priority_reason":"Byte-fidelity papercut: every POSIX .txt file gains a spurious no-trailing-newline diff on a no-op save and CRLF files are silently converted; low severity, no content loss beyond the newline/endings.","timebox_minutes":15}', 'queued', 70, 'repo-health:v1:triage:developing-today/code:issue:1307', '2026-10-27 05:47:16.297512+00', '2026-10-27 05:47:16.297512+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1295, 'repo-health-nix-pilot', 'Triage: mcp-clients Zed replacement absorbed by commented-out context_servers (issue #929, PR #910)', '{"prs":[{"url":"https://github.com/dezren39/nix/pull/910","commit":"1b6e7fb9","number":910}],"set":null,"kind":"triage","repo":"dezren39/nix","risk":{"flags":["silent-enforcement-bypass"],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/929","title":"mcp-clients: Zed replacement hits the first \"context_servers\" text match \u2014 a commented-out block absorbs the fix, foreign servers stay, success reported","number":929,"state_checked_at":"2026-10-27T05:52:00Z"},"scope":{"exclude":["other clients (Copilot/Claude/Codex) enforcement in mcp-clients.py","mcpx config itself"],"include":["mcp-clients.py _replace_context_servers / zed key location","mcp-clients.test.py regression probes"]},"tests":["mcp-clients.test.py probes: commented-out block before live foreign block -> live block replaced, comment intact, second run no-op","Existing PR #910 probes still pass"],"dedupe":{"basis":"gh issue search ''context_servers'' returned only closed origin issues #905/#906; no open issue covers the comment/string-before-key case","checked_at":"2026-10-27T05:52:00Z"},"schema":"repo-task/v1","problem":"Zed context_servers replacement targets the first text match of the key, so a commented-out block absorbs the fix and the live foreign block is never replaced.","evidence":["PR #910 (commit 1b6e7fb9) added _replace_context_servers; mcp-clients.py:162 on main 3f62139 does re.search(r''\"context_servers\"\\s*:\\s*'', text) with no comment/string skipping","Real zed() probe on main''s mcp-clients.py: input with ''// \"context_servers\": {\"old\": ...}'' before a live foreign block -> output has mcpx entry inside the comment, ''\"foreign\": {\"command\": \"evil\"}'' still configured, success message printed","mcp-clients.test.py from #910 covers braces in strings/comments inside the replaced block, but no occurrence of the key text before the real key"],"acceptance":["Re-verify the commented-out-block reproduction against current main before any fix work","Replacement locates the live top-level context_servers key, skipping comment/string occurrences; comment preserved byte-for-byte","Comment-only occurrence treated as no live key (normal insert path)","PR #910 test cases still pass; new regression probes in mcp-clients.test.py for comment-before-key and string-before-key"],"context_refs":["https://github.com/dezren39/nix/issues/929","https://github.com/dezren39/nix/pull/910"],"max_attempts":2,"priority_reason":"Silently defeats the mcpx-only enforcement for Zed (servers bypassing the gateway stay configured) while reporting success on every home-manager activation.","timebox_minutes":30}', 'done', 20, 'repo-health:v1:triage:dezren39/nix:issue:929', '2026-10-27 05:53:54.1065+00', '2026-10-27 06:12:14.136692+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1297, 'repo-health-nix-pilot', 'Triage: flag-as-value swallows --dry-run in opencode-share/clean/discovery/symlinker (issue #930, PRs #915/#921)', '{"prs":[{"url":"https://github.com/dezren39/nix/pull/915","number":915},{"url":"https://github.com/dezren39/nix/pull/916","number":916},{"url":"https://github.com/dezren39/nix/pull/921","number":921}],"set":null,"kind":"triage","repo":"dezren39/nix","risk":{"flags":["destructive-action-without-preview"],"level":"medium"},"issue":{"url":"https://github.com/dezren39/nix/issues/930","title":"value-taking options swallow the next option as their value \u2014 \"--source --dry-run\" and \"--path --dry-run\" run for real (opencode-share, clean.sh, discovery scripts, symlinker)","number":930,"state_checked_at":"2026-10-27T05:58:00Z"},"scope":{"exclude":["brew-repair -s/--skip (tracked by #927)","symlinker multi-value name-filter flags (already stop at --*)","archive/ vendored scripts"],"include":["pkgs/opencode-share/opencode-share.sh --source","clean.sh --path/--depth/--docker-age","git-discover-repos --path/--depth/--find/--user","git-maintain-repos --path/--depth/--jobs/--pack-threads/--reflog-expire","spotlight-exclude-artifacts --path/--depth","symlinker.sh --input-dir/--output-dir/--backup-suffix/--undo/--exclude"]},"tests":["opencode-share.test.sh: --source --dry-run errors, no mount attempted","symlinker.test.sh: --input-dir --dry-run style case errors, no links written","Parse probes for clean.sh/git-discover-repos/git-maintain-repos/spotlight-exclude-artifacts flag-as-value cases exit with the missing-value code"],"dedupe":{"basis":"gh issue search for the flag-as-value pattern returned only #927, which is scoped to brew-repair''s -s/--skip; no issue covers opencode-share/clean/discovery/symlinker","checked_at":"2026-10-27T05:58:00Z"},"schema":"repo-task/v1","problem":"Value-taking options in six scripts consume a following option token as their value; when that token is --dry-run the mutation runs for real.","evidence":["opencode-share.sh:318-330 on main 3f62139: --source guard is only [[ $# -lt 2 ]]; probe ''opencode-share.sh --source --dry-run /tmp/tgt'' entered check_deps (real-mount path) and hard-failed on missing bindfs instead of taking the dry-run warn-only path","git-discover-repos --path --auto probe: no parse error, script ran into a long discovery scan (killed after ~1 min)","clean.sh:198/201/207, git-maintain-repos:168/176/184-186, spotlight-exclude-artifacts:122/125, symlinker.sh:193-217: all test only $# or non-emptiness of $2 before consuming it","Contrast: symlinker name-filter consume loops from PR #916 stop at --* tokens; simple-rebuild.sh:120 already guards ''\"$2\" != --*''"],"acceptance":["Re-verify the opencode-share --source --dry-run and git-discover-repos --path --auto probes against current main before fix work","Every option listed in the issue rejects a following token starting with ''-'' in the script''s existing missing-value error shape/exit code, with no side effects","Valid values and repeated options with values unchanged","Regression coverage: opencode-share.test.sh and symlinker.test.sh gain flag-as-value cases; discovery/clean scripts get a parse probe"],"context_refs":["https://github.com/dezren39/nix/issues/930","https://github.com/dezren39/nix/pull/915","https://github.com/dezren39/nix/pull/921","https://github.com/dezren39/nix/pull/916","https://github.com/dezren39/nix/issues/927"],"max_attempts":3,"priority_reason":"--dry-run is the safety switch on opencode-share, clean.sh and symlinker.sh; a parse slip that silently discards it turns a preview into mounts/deletions/link rewrites with a success-path exit.","timebox_minutes":20}', 'done', 20, 'repo-health:v1:triage:dezren39/nix:issue:930', '2026-10-27 05:57:15.57869+00', '2026-10-27 07:25:56.936039+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1298, 'repo-health-nix-pilot', 'Triage: patch-vscode-insiders silently skips Patch 5 when JS file is missing (issue #931, PR #925)', '{"prs":[{"url":"https://github.com/dezren39/nix/pull/925","number":925}],"set":null,"kind":"triage","repo":"dezren39/nix","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/931","title":"patch-vscode-insiders: a missing JS workbench file silently skips Patch 5 and can exit 0 (PR #925 left the file-absent case unguarded)","number":931,"state_checked_at":"2026-10-27T06:05:00Z"},"scope":{"exclude":["CSS patch logic and patches 1-4","the launchd agent definition"],"include":["patch-vscode-insiders.sh JS-file presence handling","fixture coverage for the missing-JS case"]},"tests":["Fixture (retargeted /Applications path): CSS present, JS absent -> error naming Patch 5 + path, exit non-zero","Fixture: both files present scenarios from PR #925 still pass"],"dedupe":{"basis":"gh issue search returned only closed origin #909; its fix covers target-string-missing in an existing file, not the file-absent case","checked_at":"2026-10-27T06:05:00Z"},"schema":"repo-task/v1","problem":"Patch 5 is silently skipped when the JS workbench file itself is missing, and the run can exit 0.","evidence":["patch-vscode-insiders.sh on main 3f62139: lines 8-12 missing CSS file exits 1; line 98 JS_FILE path; line 100 ''if [ -f \"$JS_FILE\" ]'' with no else and no status update","PR #925 verification list covers present-but-unrelated JS content, not an absent JS file; PR notes no nix package/check covers this script"],"acceptance":["Re-verify the file-absent case against current main before fix work","CSS present + JS absent: error naming Patch 5 and the missing JS path, exit non-zero, CSS patches still attempted/reported","Both files present: behaviour unchanged from main (applied / already-applied / target-missing, write-back only when changed)","Fixture run covers the missing-JS-file case"],"context_refs":["https://github.com/dezren39/nix/issues/931","https://github.com/dezren39/nix/pull/925"],"max_attempts":3,"priority_reason":"The script''s exit code/log line is its only failure signal (per PR #925); a VSCode update moving the JS file is exactly when Patch 5''s signal should fire.","timebox_minutes":20}', 'cancelled', 30, 'repo-health:v1:triage:dezren39/nix:issue:931', '2026-10-27 06:01:34.69624+00', '2026-10-27 07:31:13.275444+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1299, 'repo-health-opencode-pilot', 'triage: Identifier sortable-prefix wrap (#561)', '{"prs":[],"set":null,"kind":"triage","repo":"developing-today/opencode","risk":{"flags":[],"level":"medium"},"issue":{"url":"https://github.com/developing-today/opencode/issues/561","title":"fix(schema): Identifier sortable prefix wrapped on 2026-08-14 \u2014 ascending/descending IDs now misorder across the 2^36 ms boundary","number":561,"state_checked_at":"2026-10-27T06:00:00Z"},"scope":{"exclude":["Changing the 26-char ID shape or alphabet without an explicit decision on #561"],"include":["packages/schema/src/identifier.ts","packages/schema/src/session-id.ts and event.ts consumers (read-only assessment)"]},"tests":["bun test in packages/schema (after fix follow-up)"],"dedupe":{"basis":"gh issue list --state all searches for identifier ascending / ID sort wrap returned no covering issue","checked_at":"2026-10-27T06:00:00Z"},"schema":"repo-task/v1","problem":"Sortable ID prefix discards the high bits of the packed timestamp, wrapping every 2^36 ms and inverting ascending/descending order across the boundary.","evidence":["Probe on main 58d2a8277f (bun, real module): ascending now 17bf34a93001 vs yearAgo a24421e93001 (now>old false); descending now e840cb56cffe vs yearAgo 5dbbde16cffe (now<old false)","identifier.ts: emits 6 bytes via shifts 40..0 of a ~53-bit value; wrap boundary 26*2^36 ms = 2026-08-14T11:19:55Z; prefix goes ffffffc18001 -> 0000003e8001 across it"],"acceptance":["A decision is recorded on #561: new encoding (or scoped correction) plus explicit treatment of pre-fix IDs","Follow-up fix packet enqueued with cross-boundary ordering tests in packages/schema/test named"],"context_refs":["https://github.com/developing-today/opencode/issues/561"],"max_attempts":2,"priority_reason":"Session and event IDs are chronological sort keys; everything minted since 2026-08-14 misorders against the prior year. High priority, but the fix needs a design decision, so triage not small_fix.","timebox_minutes":30}', 'done', 20, 'repo-health:v1:triage:developing-today/opencode:issue:561', '2026-10-27 06:04:35.803611+00', '2026-10-27 08:41:16.980178+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1300, 'repo-health-code-pilot', 'Implement journal rollback contract for ExecutionProfile entries (bump-on-first-write) — issue #227', '{"kind":"small_fix","repo":"developing-today/code","risk":{"flags":["journal-format","operator-state"],"level":"medium"},"issue":{"url":"https://github.com/developing-today/code/issues/227","title":"Define rollback compatibility for world profile journal entries","number":227,"state_checked_at":"2026-10-27T06:20:00Z"},"scope":{"exclude":["F11.12 journal check/backup commands","Phase 13 new frame kinds"],"include":["pkgs/id journal versioning (world/core.rs, world/actor.rs persist path)","cross-version fixture test","journal code docs"]},"tests":["cargo test for pkgs/id journal tests incl. new cross-version fixture test","nix flake check for pkgs/id fast lane (id workflow PR gate)"],"dedupe":{"basis":"One implementation task per issue; triage task 1260 created it after verifying no small_fix packet exists for #227.","checked_at":"2026-10-27T06:20:00Z"},"schema":"repo-task/v1","problem":"ExecutionProfile journal entries are appended under the v1 header (core.rs:453 writes JOURNAL_VERSION; actor.rs:1256 persists the entry), so an older binary accepts the header and fails mid-read instead of refusing early at the version check (core.rs:152).","evidence":["Issue #227 acceptance criteria","Triage findings + chosen contract: issue #227 agent note from queue task 1260 (2026-10-27)","Code on main dd4ee06e: actor.rs:1256, core.rs:152/244/453/503"],"acceptance":["Issue #227 acceptance criteria met: written contract recorded in journal code/docs; older binary refuses a v2 journal at header check; v1 journals remain readable; bump is atomic (temp+fsync+rename) with a cross-version fixture test","PR opened (and merged under standing criteria) referencing issue #227"],"context_refs":["https://github.com/developing-today/code/issues/227"],"max_attempts":3,"priority_reason":"Path to Phase 12 step 8 follow-up: #227 blocks safe rollback once profile entries are written and gates Phase 13 new frame kinds per the gate note on the issue.","timebox_minutes":45}', 'done', 20, 'repo-health:v1:fix:developing-today/code:issue:227', '2026-10-27 06:07:54.989243+00', '2026-10-27 10:59:14.036369+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1303, 'repo-health-opencode-pilot', 'fix(util): clamp retry attempts to at least 1 (#562)', '{"prs":[],"set":null,"kind":"small_fix","repo":"developing-today/opencode","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/opencode/issues/562","title":"fix(util): retry with attempts <= 0 never calls the operation and throws undefined","number":562,"state_checked_at":"2026-10-27T06:10:00Z"},"scope":{"exclude":["Changing retryIf/transient-error classification","Changing default attempts/delay/factor"],"include":["packages/util/src/retry.ts attempts normalization","packages/util/src/retry.test.ts regression tests"]},"tests":["bun test src/retry.test.ts from packages/util"],"dedupe":{"basis":"gh issue list --state all searches for retry attempts / util retry returned no covering issue (#85 is an unrelated TUI writeJsonAtomic retry)","checked_at":"2026-10-27T06:10:00Z"},"schema":"repo-task/v1","problem":"retry() with attempts <= 0 silently skips the operation and throws undefined instead of running once or failing with a real error.","evidence":["Probe on main 58d2a8277f (bun, real module, hidden_files/probe-2026-10-27-0052/out-retry.log): attempts:0 threw undefined with calls 0; attempts:-1 threw undefined; attempts:1 threw Error: boom","retry.ts:35 attempts taken verbatim; :42 loop skipped when attempts <= 0; :51 throw lastError throws undefined"],"acceptance":["retry with attempts 0 runs the operation exactly once and returns its result","retry with attempts -1 and a failing operation throws that operation''s real error, never undefined","Default and positive-attempts behavior unchanged","bun test src/retry.test.ts from packages/util passes"],"context_refs":["https://github.com/developing-today/opencode/issues/562"],"max_attempts":2,"priority_reason":"Latent footgun in a shared utility: no live caller passes attempts <= 0 tod