INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1433, 'repo-health-nix-pilot', 'Small fix: mcp-clients Codex root-level dotted/inline spellings survive (issue #956)', '{"prs":[],"set":null,"kind":"small_fix","repo":"dezren39/nix","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/956","title":"mcp-clients: Codex servers spelled as root-level dotted keys or a root inline table survive enforcement - the inline-table spelling leaves config.toml invalid TOML","number":956,"state_checked_at":"2026-10-27T15:16:00Z"},"scope":{"exclude":["header and [mcp_servers]-parent spellings already handled by #944","the Zed/Claude/Copilot client paths"],"include":["mcp-clients.py codex() root-level assignment handling","mcp-clients.test.py root-spelling cases"]},"tests":["Dotted-key seed -> evil dropped, named in removed:, only mcpx remains","Root inline-table seed -> evil dropped and output parses with tomllib","Idempotence: second run makes no change","Full mcp-clients.test.py suite passes"],"dedupe":{"basis":"gh search for dotted/root-level Codex spellings returned no covering issue; closed #944 covers inline entries under the [mcp_servers] parent header and [[mcp_servers.*]] array tables only - its test seeds are all header forms. #950/#929/#905 are the Zed path, not Codex.","checked_at":"2026-10-27T15:16:00Z"},"schema":"repo-task/v1","problem":"Codex mcp_servers entries spelled at the TOML root (dotted keys or an inline table) are not enforced; the inline-table case also leaves config.toml unparseable.","evidence":["Main 7b6590e, mcp-clients.py codex() at :166; root-level lines reach the unconditional kept.append(line) at :223; mcpx block appended at :224-231","Scratch-HOME probe, dotted-key seed: exit 0, ''mcp_servers = mcpx only (removed: none)'', evil lines still present after run 1 and run 2; output TOML valid","Scratch-HOME probe, root inline-table seed: exit 0, ''removed: none'', evil present; tomllib.load fails: Cannot declare (''mcp_servers'', ''mcpx'') twice","mcp-clients.test.py seeds only header forms for Codex ([mcp_servers.*], [[...]], [mcp_servers] parent) - no root-level dotted or inline seed"],"acceptance":["Root dotted-key Codex seed: foreign server dropped and named in removed:, only [mcp_servers.mcpx] remains, exit 0","Root inline-table seed (single- and multi-line): foreign server dropped, resulting file parses as valid TOML","Re-run on an enforced file is a no-op","Unrelated root keys (model = ..., non-mcp_servers dotted keys) preserved byte-for-byte","mcp-clients.test.py gains both-spelling cases; full suite passes incl. #944 cases"],"context_refs":["https://github.com/dezren39/nix/issues/956"],"max_attempts":2,"priority_reason":"mcp-clients runs on every home-manager switch to make mcpx the only MCP server; a silently-surviving spelling is a permanent bypass, and the inline-table spelling corrupts Codex''s config while reporting success.","timebox_minutes":45}', 'done', 30, 'repo-health:v1:fix:dezren39/nix:issue:956', '2026-10-27 15:25:16.60124+00', '2026-10-27 16:23:10.605498+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1434, 'repo-health-code-pilot', 'Fix #1430: nightly-backup status step SIGPIPE/pipefail spurious failure', '{"kind":"small_fix","repo":"developing-today/code","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/developing-today/code/issues/1430","title":"cold-store-reaper: nightly-backup status step spuriously FAILED when status prints >20 lines \u2014 head closes the pipe, SIGPIPE + pipefail fail a healthy run","number":1430,"state_checked_at":"2026-10-27T15:26:00Z"},"scope":{"exclude":["changing what cold-store status prints","changing any other nightly step''s semantics"],"include":["scripts/nightly-backup.sh status-step pipeline","tests/test_nightly_backup.py regression case with a >20-line stub status"]},"tests":["python3 -m unittest pkgs/cold-store-reaper/tests/test_nightly_backup.py (targeted file) plus repeated stub runs per the acceptance criteria"],"dedupe":{"basis":"issue number; issue search for nightly-backup/head/SIGPIPE found no prior filing","checked_at":"2026-10-27T15:26:00Z"},"schema":"repo-task/v1","problem":"Make the nightly status step''s verdict depend only on cold-store status''s own exit code while keeping display truncation.","evidence":["nightly-backup.sh runs set -uo pipefail and the status step is: if ${COLD_STORE} status | head -n 20","Reproduced this run on main 37418e56 via COLD_STORE_BIN/EXPORT_TURSO_BIN seams: stub status printing 100 lines and exiting 0 -> runs 1-2 ok, run 3 ''step status: FAILED'', script exit 1","tests/test_nightly_backup.py stub status prints exactly one line, so the existing tests cannot trigger the early pipe close","The real cold-store is Python: SIGPIPE surfaces as BrokenPipeError at flush, also a non-zero exit"],"acceptance":["Status step reports ok whenever cold-store status itself exits 0, regardless of line count (stub printing several hundred lines, 20 consecutive runs, zero spurious failures)","A genuinely failing cold-store status still marks the step FAILED and the script exits non-zero","Printed summary still truncated to ~20 lines for display","tests/test_nightly_backup.py gains a >20-line stub-status case asserting step status: ok and exit 0"],"context_refs":["https://github.com/developing-today/code/issues/1430","https://github.com/developing-today/code/issues/1427"],"max_attempts":2,"priority_reason":"Issue carries priority/normal; a flaky failure verdict on the nightly backup trains operators to ignore real failures.","timebox_minutes":45}', 'queued', 50, 'repo-health:v1:fix:developing-today/code:issue:1430', '2026-10-27 15:27:05.972239+00', '2026-10-27 15:27:05.972239+00') ON CONFLICT(id) DO UPDATE SET queue=excluded.queue, title=excluded.title, payload=excluded.payload, status=excluded.status, priority=excluded.priority, dedupe_key=excluded.dedupe_key, updated_at=excluded.updated_at;
INSERT INTO coord_tasks (id, queue, title, payload, status, priority, dedupe_key, created_at, updated_at) VALUES (1435, 'repo-health-nix-pilot', 'Small fix: search.sh failed brew list reports every app (issue #957)', '{"prs":[],"set":null,"kind":"small_fix","repo":"dezren39/nix","risk":{"flags":[],"level":"low"},"issue":{"url":"https://github.com/dezren39/nix/issues/957","title":"search.sh: a failed ''brew list'' reports every app as not brew-installed and exits 0 \u2014 brew''s error is discarded","number":957,"state_checked_at":"2026-10-27T15:28:00Z"},"scope":{"exclude":["brew-repair.sh (covered by #949)","the per-app brew search call at search.sh:35, which is already || true best-effort"],"include":["search.sh cask-list capture at :10-11"]},"tests":["Stub brew list exits 1 -> non-zero exit, step named on stderr, no findings","Stub brew list prints foo -> only bar reported","No brew on PATH -> loud failure, not an all-apps report"],"dedupe":{"basis":"gh issue list --search ''search.sh'' returned no covering issue in any state; open #949 covers pkgs/brew-repair/brew-repair.sh:69 only and its scope excludes other scripts.","checked_at":"2026-10-27T15:28:00Z"},"schema":"repo-task/v1","problem":"search.sh cannot distinguish ''brew list failed'' from ''no casks installed'' and reports a broken Homebrew as ''no apps were installed through Homebrew''.","evidence":["Main 7b6590e, search.sh:10-11: mapfile from process substitutions with 2>/dev/null; no status check anywhere in the script","Stub-brew probe, working list (prints foo): output ''bar'' only, exit 0","Stub-brew probe, list exits 1 with stderr: output ''foo'' + ''bar'' (foo falsely flagged), stderr never shown, exit 0"],"acceptance":["brew list failure: stderr error naming the brew list step, non-zero exit, no app findings printed","Missing brew on PATH produces the same loud failure","Working brew: cask-installed apps not reported, others reported, unchanged output shape","brew list runs once per invocation, not